using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class ExternalOrderMappingConfiguration:IEntityTypeConfiguration<ExternalOrderMapping>{public void Configure(EntityTypeBuilder<ExternalOrderMapping>b){b.ToTable("ExternalOrderMappings");b.HasKey(x=>x.Id);b.Property(x=>x.ExternalOrderId).HasMaxLength(200).IsRequired();b.Property(x=>x.ExternalParcelId).HasMaxLength(200);b.HasIndex(x=>new{x.ConnectionId,x.ExternalOrderId}).IsUnique();}}
